for spec in "centralindia Standard_B2pts_v2 Canonical:ubuntu-24_04-lts:server-arm64:latest" "southindia Standard_B2ats_v2 Ubuntu2404" "southindia Standard_B1s Ubuntu2404" "southindia Standard_B2pts_v2 Canonical:ubuntu-24_04-lts:server-arm64:latest"; do set -- $spec; VMN=rb-$1; echo "Trying $2 in $1..."; az vm create -g resume-builder -n $VMN -l $1 --image $3 --size $2 --admin-username azureuser --generate-ssh-keys --public-ip-sku Standard --os-disk-size-gb 64 --storage-sku Premium_LRS -o none --only-show-errors && OK=1 && break; done; [ "$OK" = 1 ] && az vm open-port -g resume-builder -n $VMN --port 80,443 --priority 900 -o none && echo "===== SERVER IP =====" && az vm show -d -g resume-builder -n $VMN --query publicIps -o tsv && echo "===== PRIVATE KEY =====" && cat ~/.ssh/id_rsa
